const parseTimeToMinutes = (timeStr: string): number => {
  if (!timeStr) return 480;
  const cleaned = timeStr.trim().toUpperCase();
  const match = cleaned.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)?$/);
  if (!match) return 480;
  let hours = parseInt(match[1], 10);
  const minutes = parseInt(match[2], 10);
  const ampm = match[3];
  if (ampm === 'PM' && hours < 12) hours += 12;
  if (ampm === 'AM' && hours === 12) hours = 0;
  return hours * 60 + minutes;
};

const formatMinutesToTime = (totalMins: number): string => {
  const normMins = ((totalMins % 1440) + 1440) % 1440;
  let hours = Math.floor(normMins / 60);
  const minutes = normMins % 60;
  const ampm = hours >= 12 ? 'PM' : 'AM';
  hours = hours % 12;
  if (hours === 0) hours = 12;
  const hStr = hours < 10 ? `0${hours}` : `${hours}`;
  const mStr = minutes < 10 ? `0${minutes}` : `${minutes}`;
  return `${hStr}:${mStr} ${ampm}`;
};

const calculateIntervalDoseTimes = (
  anchorTime: string = '08:00 AM',
  intervalHours: number = 8,
  cycleMode: '24h_continuous' | 'waking_hours' = 'waking_hours',
  wakingStart: string = '08:00 AM',
  wakingEnd: string = '10:00 PM'
): string[] => {
  const intervalMins = Math.max(1, intervalHours) * 60;
  const anchorMins = parseTimeToMinutes(anchorTime);

  if (cycleMode === '24h_continuous') {
    const totalDoses = Math.min(24, Math.floor(1440 / intervalMins));
    const times: string[] = [];
    for (let i = 0; i < totalDoses; i++) {
      times.push(formatMinutesToTime(anchorMins + i * intervalMins));
    }
    return times.length > 0 ? times : [anchorTime];
  } else {
    const wakingStartMins = parseTimeToMinutes(wakingStart);
    let wakingEndMins = parseTimeToMinutes(wakingEnd);
    if (wakingEndMins <= wakingStartMins) wakingEndMins += 1440;

    const times: string[] = [];
    let currentMins = anchorMins < wakingStartMins ? wakingStartMins : anchorMins;
    
    let attempts = 0;
    while (currentMins <= wakingEndMins && attempts < 12) {
      times.push(formatMinutesToTime(currentMins));
      currentMins += intervalMins;
      attempts++;
    }
    return times.length > 0 ? times : [anchorTime];
  }
};

const getNextWeeklyDoseText = (days: string[] = [], timeStr: string = '09:00 AM'): string => {
  if (days.length === 0) return 'No days selected';
  const dayMap: { [key: string]: number } = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };
  const now = new Date();
  const currentDayNum = now.getDay();
  
  const targetDayNums = days.map(d => dayMap[d]).filter(n => n !== undefined).sort((a,b) => a - b);
  if (targetDayNums.length === 0) return 'No days selected';

  let daysUntilNext = 99;
  for (const dNum of targetDayNums) {
    let diff = dNum - currentDayNum;
    if (diff < 0) diff += 7;
    if (diff === 0) {
      const doseMins = parseTimeToMinutes(timeStr);
      const currentMins = now.getHours() * 60 + now.getMinutes();
      if (currentMins < doseMins) {
        daysUntilNext = 0;
        break;
      } else {
        diff = 7;
      }
    }
    if (diff < daysUntilNext) daysUntilNext = diff;
  }

  if (daysUntilNext === 0) return `Today at ${timeStr}`;
  if (daysUntilNext === 1) return `Tomorrow at ${timeStr}`;
  
  const targetDate = new Date(now.getTime() + daysUntilNext * 86400000);
  const dayName = targetDate.toLocaleDateString('en-US', { weekday: 'short' });
  return `Next ${dayName} (${targetDate.getMonth()+1}/${targetDate.getDate()}) at ${timeStr}`;
};

const getPrnStatus = (lastDoseTime: number | null | undefined, minIntervalHours: number = 4) => {
  if (!lastDoseTime) {
    return { locked: false, hoursSince: 999, minsRemaining: 0, timeStr: '0m', statusText: '✅ Safe to take PRN dose' };
  }
  const hoursSince = (Date.now() - lastDoseTime) / 3600000;
  const locked = hoursSince < minIntervalHours;
  const minsRemaining = Math.max(0, Math.ceil((minIntervalHours - hoursSince) * 60));
  const hrsRem = Math.floor(minsRemaining / 60);
  const mRem = minsRemaining % 60;
  const timeStr = hrsRem > 0 ? `${hrsRem}h ${mRem}m` : `${mRem}m`;
  return {
    locked,
    hoursSince,
    minsRemaining,
    timeStr,
    statusText: locked ? `🛑 Double-Dose Lockout Active (${timeStr} remaining)` : `✅ Safe to take PRN dose`
  };
};

