  // Fall Detection (DeviceMotion)
  useEffect(() => {
    if (Platform.OS === 'web') {
      const handleMotion = (event: DeviceMotionEvent) => {
        const acc = event.accelerationIncludingGravity;
        if (acc && acc.x !== null && acc.y !== null && acc.z !== null) {
          const magnitude = Math.sqrt(acc.x * acc.x + acc.y * acc.y + acc.z * acc.z);
          if (magnitude > 28) { // Threshold for sudden impact/fall
            triggerEmergency("Sudden fall detected by device sensors");
          }
        }
      };
      window.addEventListener('devicemotion', handleMotion);
      return () => window.removeEventListener('devicemotion', handleMotion);
    }
  }, []);

  // Continuous Distress Listening (Voice + Volume)
  useEffect(() => {
    let audioContext: AudioContext;
    let analyser: AnalyserNode;
    let microphone: MediaStreamAudioSourceNode;
    let volumeInterval: any;

    if (Platform.OS === 'web' && distressListening) {
      // 1. Keyword Recognition
      const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
      if (SpeechRecognition) {
        const rec = new SpeechRecognition();
        rec.continuous = true;
        rec.interimResults = false;
        rec.lang = 'en-US';

        rec.onresult = (event: any) => {
          for (let i = event.resultIndex; i < event.results.length; ++i) {
            const transcript = event.results[i][0].transcript.toLowerCase();
            const painWords = ['help', 'emergency', 'distress', 'ah', 'ahh', 'ahhh', 'ouch', 'it hurts', 'stop'];
            if (painWords.some(word => transcript.includes(word))) {
              triggerEmergency("Pain or distress phrase recognized");
            }
          }
        };

        rec.onend = () => {
          if (distressListening) {
            try { rec.start(); } catch(e){}
          }
        };
        
        try { rec.start(); } catch(e){}
        recognitionRef.current = rec;
      }

      // 2. Volume/Screaming Detection
      navigator.mediaDevices.getUserMedia({ audio: true }).then(stream => {
        audioContext = new (window.AudioContext || (window as any).webkitAudioContext)();
        analyser = audioContext.createAnalyser();
        microphone = audioContext.createMediaStreamSource(stream);
        microphone.connect(analyser);
        analyser.fftSize = 256;
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);

        volumeInterval = setInterval(() => {
          analyser.getByteFrequencyData(dataArray);
          let sum = 0;
          for (let i = 0; i < bufferLength; i++) {
            sum += dataArray[i];
          }
          const average = sum / bufferLength;
          if (average > 105) {
            triggerEmergency("Loud sound / screaming detected");
          }
        }, 500);
      }).catch(err => console.log('Mic error for volume detection', err));

      return () => {
        if (recognitionRef.current) recognitionRef.current.stop();
        if (volumeInterval) clearInterval(volumeInterval);
        if (audioContext) audioContext.close();
      };
    } else {
      if (recognitionRef.current) recognitionRef.current.stop();
    }
  }, [distressListening]);

  const speakText = (text: string) => {
    if (Platform.OS === 'web' && voiceEnabled && 'speechSynthesis' in window) {
      window.speechSynthesis.cancel();
      // Phonetically vocalize "aw-gor" (as in augor) smoothly and naturally while keeping all written text cleanly styled as Ogoo
      const spokenText = text
        .replace(/\bOgoo\b/g, 'Aw-gor')
        .replace(/\bogoo\b/g, 'aw-gor')
        .replace(/\bOGOO\b/g, 'Aw-gor');
      const utterance = new SpeechSynthesisUtterance(spokenText);
      
      // Select Nigerian female voice for Ogoo
      const voices = window.speechSynthesis.getVoices();
      const ngFemaleVoice = voices.find(v => 
        (v.lang === 'en-NG' || v.lang === 'en_NG' || v.lang.toLowerCase().includes('en-ng') || v.lang.toLowerCase().includes('pcm')) &&
        (v.name.toLowerCase().includes('female') || v.name.toLowerCase().includes('ebele') || v.name.toLowerCase().includes('chioma') || !v.name.toLowerCase().includes('male'))
      ) || voices.find(v => 
        v.lang === 'en-NG' || v.lang === 'en_NG' || v.name.toLowerCase().includes('nigeria')
      ) || voices.find(v => 
        v.lang.startsWith('en') && (v.name.toLowerCase().includes('female') || v.name.toLowerCase().includes('samantha') || v.name.toLowerCase().includes('karen') || v.name.toLowerCase().includes('victoria') || v.name.toLowerCase().includes('zira') || v.name.toLowerCase().includes('serena') || v.name.toLowerCase().includes('natural'))
      ) || null;

      if (ngFemaleVoice) {
        utterance.voice = ngFemaleVoice;
      }
      utterance.lang = 'en-NG';
      utterance.pitch = 1.08; // Warm, melodious pitch
      utterance.rate = 0.96;  // Clear, caring clinical cadence
      window.speechSynthesis.speak(utterance);
    }
  };
  
