                    <TouchableOpacity onPress={() => logMetric('screenTime', parseFloat((activityData.screenTime + 0.5).toFixed(1)))}><Text style={{color: COLORS.accent, fontSize: 22, paddingHorizontal: 10}}>+</Text></TouchableOpacity>
