      const now = Date.now();
      setPrnLastDoseTime(now);
      if (Platform.OS === 'web') {
        localStorage.setItem('ogoo_prn_last_dose', now.toString());
      }
      alert(`PRN Dose for ${prnMedTitle} recorded! Minimum ${prnMinIntervalHours}-hour safety lockout timer restarted.`);
