  const handlePickChatAttachment = (specificType: 'all' | 'image' | 'document' | 'video' = 'all') => {
    setShowAttachmentMenu(false);
    if (Platform.OS === 'web') {
      const input = document.createElement('input');
      input.type = 'file';
      if (specificType === 'image') {
        input.accept = 'image/*';
      } else if (specificType === 'document') {
        input.accept = 'application/pdf,.pdf,.doc,.docx,.txt,.csv';
      } else if (specificType === 'video') {
        input.accept = 'video/*,.mp4,.mov,.webm';
      } else {
        input.accept = 'image/*,application/pdf,.pdf,.doc,.docx,.txt,video/*,.mp4,.mov,.webm';
      }
      input.onchange = (e: any) => {
        const file = e.target.files?.[0];
        if (!file) return;
        const reader = new FileReader();
        reader.onload = () => {
          const res = reader.result as string;
          const base64String = res.includes(',') ? res.split(',')[1] : res;
          let detectedType: 'image' | 'document' | 'video' = 'image';
          if (file.type.startsWith('video/')) detectedType = 'video';
          else if (file.type.includes('pdf') || file.name.endsWith('.pdf') || file.type.includes('document')) detectedType = 'document';

          setSelectedAttachment({
            type: detectedType,
            base64: base64String,
            uri: res,
            mimeType: file.type || (detectedType === 'document' ? 'application/pdf' : detectedType === 'video' ? 'video/mp4' : 'image/jpeg'),
            name: file.name,
            size: file.size
          });
        };
        reader.readAsDataURL(file);
      };
      input.click();
    }
  };

